import { forensicTeaching } from './forensics';
import { b, type Bilingual } from './core';

export type TeachingUnit={mechanism:Bilingual;case:Bilingual;reason:Bilingual;limit:Bilingual;frames:Bilingual[];recall:Bilingual;answer:Bilingual;transfer:Bilingual;transferAnswer:Bilingual};
const unit=(mechanism:Bilingual,caseText:Bilingual,reason:Bilingual,limit:Bilingual,frames:Bilingual[],recall:Bilingual,answer:Bilingual,transfer:Bilingual,transferAnswer:Bilingual):TeachingUnit=>({mechanism,case:caseText,reason,limit,frames,recall,answer,transfer,transferAnswer});
export const teachingUnits:Record<string,TeachingUnit>={m25:forensicTeaching,
m24:unit(
b('Contenção limita o dano em andamento; erradicação trata a causa e acessos; recuperação demonstra que dados e funções podem voltar. Preservar evidências com origem e horário ajuda a justificar decisões. Atividades podem se sobrepor conforme risco e plano.','Containment limits ongoing harm; eradication addresses cause and access; recovery demonstrates that data and functions can return. Preserving evidence with source and time supports decisions. Activities may overlap according to risk and plan.'),
b('Lia isolou N-24. O portal abre após o backup, mas a sessão cloud indevida ainda consegue ler notas. Ela pode declarar o incidente resolvido? Explique antes de avançar.','Lia isolated N-24. The portal opens after backup, but the unauthorized cloud session still reads grades. Can she declare the incident resolved? Explain before proceeding.'),
b('Não: isolar a estação não revoga a sessão cloud. A equipe precisa tratar a causa e os acessos, verificar o backup e testar função e rejeição da sessão antiga antes do retorno autorizado e monitorado.','No: isolating the workstation does not revoke the cloud session. The team must address cause and access, verify backup and test function and rejection of the old session before authorized monitored return.'),
b('A bancada representa decisões, não coleta forense. A ordem não é universal: contenção urgente e preservação podem ocorrer em paralelo. Sem cobertura completa, os testes de N-24 não comprovam segurança de toda a escola.','The bench represents decisions, not forensic collection. Order is not universal: urgent containment and preservation can overlap. Without complete coverage, N-24 tests do not prove safety across the school.'),
[b('Alteração indevida confirmada','Unauthorized change confirmed'),b('Conter e preservar com autorização','Contain and preserve with authority'),b('Tratar causa, acessos e testar','Address cause, access and test'),b('Retorno gradual com acompanhamento','Gradual return with follow-up')],
b('Sem consultar: qual a diferença entre contenção e recuperação?','Without looking: what is the difference between containment and recovery?'),b('Contenção limita dano e expansão. Recuperação restaura e testa dados e funções para retorno autorizado, após tratar a causa e acessos indevidos.','Containment limits harm and spread. Recovery restores and tests data and functions for authorized return after addressing cause and unauthorized access.'),
b('A direção pede o retorno imediato: o backup passou no hash, mas a sessão antiga ainda funciona. O que você recomenda e por quê?','Management requests immediate return: backup passed hash checks, but the old session still works. What do you recommend and why?'),b('Não liberar ainda: o hash não prova que os acessos foram corrigidos. Revogue a sessão indevida, trate a causa e teste dados e função; obtenha aprovação para retorno gradual com monitoramento.','Do not release yet: the hash does not prove access was corrected. Revoke the unauthorized session, address the cause and test data and function; obtain approval for gradual return with monitoring.')),

m1:unit(
b('Uma credencial é uma prova usada para entrar. Uma senha exclusiva faz o vazamento de uma conta parar nessa conta, em vez de abrir várias portas. Comprimento ajuda a resistir a tentativas de adivinhação; exclusividade reduz o reaproveitamento. MFA acrescenta uma categoria diferente de prova. O gerenciador organiza as senhas, mas seu acesso e sua recuperação também precisam de proteção.','A credential is evidence used to sign in. A unique password keeps a leak in one account from opening several doors. Length helps resist guessing; uniqueness reduces reuse. MFA adds a different category of evidence. A manager organizes passwords, but its access and recovery also need protection.'),
b('Lia usa a mesma senha na loja e no e-mail. A loja avisa que houve vazamento. Ela troca apenas a senha da loja e acredita que resolveu tudo. Antes de avançar: a senha antiga ainda funciona no e-mail?','Lia uses one password for the shop and email. The shop reports a leak. She changes only the shop password and thinks everything is fixed. Before proceeding: does the old password still work in email?'),
b('Sim: a troca na loja não modifica o e-mail. Lia deve substituir a senha reutilizada nos outros serviços pelos canais oficiais, conferir acessos e proteger a recuperação. Depois usa senhas independentes e MFA. É como trocar a fechadura de uma porta: as outras fechaduras iguais continuam aceitando a chave antiga.','Yes: changing the shop password does not change email. Lia should replace reused passwords through official channels, review access and protect recovery. Then use independent passwords and MFA. Changing one lock does not change other locks that accept the old key.'),
b('A analogia da chave explica reutilização, mas contas também têm sessões, recuperação e outros acessos. Uma senha forte não impede todos os golpes; não aprove pedidos de MFA inesperados.','The key analogy explains reuse, but accounts also have sessions, recovery and other access. A strong password does not prevent every scam; do not approve unexpected MFA requests.'),
[b('Credencial da loja vaza','Shop credential leaks'),b('Mesma chave é tentada no e-mail','Same key is tried in email'),b('Senhas independentes interrompem o caminho','Independent passwords interrupt the path'),b('MFA e recuperação completam as camadas','MFA and recovery add layers')],
b('Sem consultar: por que senha + PIN não são dois fatores?','Without looking: why are password + PIN not two factors?'),b('Os dois são algo que você sabe. MFA combina categorias, como algo que sabe e um dispositivo que tem. Dois segredos na mesma categoria não bastam.','Both are something you know. MFA combines categories, such as something you know and a device you have. Two secrets in the same category are insufficient.'),
b('Você recebe um pedido de MFA durante uma aula, sem tentar entrar. Qual é sua decisão e por quê?','You receive an MFA request in class without trying to sign in. What do you do and why?'),b('Recuso e verifico a conta pelo app oficial. O pedido pode ser de outra pessoa que conhece minha senha; aprová-lo pode liberar o acesso.','Decline and check through the official app. Someone else may know my password; approving could grant access.')),
m2:unit(
b('Phishing combina uma história convincente com um pedido que beneficia quem engana: clicar, pagar, instalar ou revelar um segredo. Urgência reduz seu tempo de reflexão; autoridade imitada empresta confiança. A investigação pergunta quem pediu, o que pediu e como confirmar fora da mensagem. Um sinal isolado é uma pista, não um veredito.','Phishing combines a convincing story with a request that benefits the deceiver: click, pay, install or reveal a secret. Urgency reduces reflection; impersonated authority borrows trust. Ask who requested what and how to verify outside the message. A single sign is a clue, not a verdict.'),
b('Uma mensagem com logo da transportadora diz: “Pague a taxa em dez minutos; envie o código recebido para liberar a encomenda”. Você comprou algo ontem. Isso torna a mensagem confiável?','A message with the carrier logo says: “Pay the fee in ten minutes; send the code you received to release the parcel.” You bought something yesterday. Does that make it trustworthy?'),
b('O contexto aumenta a plausibilidade, mas não confirma a origem. Logo pode ser copiado e o código pode autorizar acesso ou pagamento. Pare, abra o app oficial por conta própria e confira a entrega. Se precisar de suporte, use um contato conhecido, não o telefone da mensagem.','The context makes it plausible but does not confirm origin. A logo can be copied and the code could authorize access or payment. Pause, open the official app independently and check the delivery. Use a known support contact rather than the message phone number.'),
b('Erros de escrita não são obrigatórios em golpes. Um remetente legítimo também pode estar comprometido; confirme pedidos incomuns mesmo quando o endereço parece correto.','Scams need not contain spelling mistakes. A legitimate sender can be compromised; verify unusual requests even when the address looks correct.'),
[b('História parece familiar','Story feels familiar'),b('Prazo e segredo criam pressão','Deadline and secrecy add pressure'),b('Você interrompe a pressa','You interrupt the rush'),b('Canal independente confirma o pedido','Independent channel verifies the request')],
b('Sem reler: qual é a diferença entre verificar um pedido e ligar para o número da mensagem?','Without rereading: how is verification different from calling the message number?'),b('Verificar exige uma fonte independente. O número na mensagem pode levar à mesma pessoa que criou o golpe; ele não confirma a própria história.','Verification needs an independent source. The supplied number may reach the same scammer and cannot independently verify the story.'),
b('O diretor pede um pagamento urgente por uma conta conhecida. Que detalhe ainda falta?','The director requests urgent payment from a known account. What is still missing?'),b('Confirmação do pedido por um canal já conhecido e conforme o procedimento. Uma conta conhecida pode ter sido tomada; autoridade aparente não dispensa verificação.','Confirmation through a previously known channel and the normal process. A known account can be taken over; apparent authority does not remove verification.')),
m3:unit(
b('Separe destino e transporte. O host identifica para onde a conexão vai; o caminho identifica um recurso naquele destino. HTTPS usa TLS para proteger a comunicação e verificar o certificado do host. Ele não avalia a honestidade do conteúdo. VPN muda parte do trajeto e modo anônimo reduz registros locais: nenhum dos dois torna um pedido legítimo.','Separate destination and transport. The host identifies the connection destination; the path identifies a resource there. HTTPS uses TLS to protect communication and verify the host certificate. It does not judge content honesty. VPN changes part of the route and private browsing reduces local records; neither makes a request legitimate.'),
b('Você vê https://suporte.example/nexus/login. A palavra nexus aparece, há HTTPS e a página pede sua senha da NEXUS. Qual parte identifica o responsável pelo destino?','You see https://suporte.example/nexus/login. The word nexus appears, HTTPS is present and the page asks for your NEXUS password. Which part identifies the destination?'),
b('O host é suporte.example; nexus/login é caminho. A palavra da instituição no caminho não transforma o site em NEXUS. Confira o endereço oficial por uma fonte conhecida. HTTPS protege o trajeto até suporte.example, inclusive se o conteúdo desse destino for enganoso.','The host is suporte.example; nexus/login is the path. The institution name in the path does not make the site NEXUS. Check the official address through a known source. HTTPS protects the route to suporte.example even if that destination contains deceptive content.'),
b('Leia a URL completa. Userinfo antes de @, subdomínios e nomes parecidos podem confundir. Avisos de certificado exigem investigação; não os ignore para continuar.','Read the complete URL. Userinfo before @, subdomains and similar names can confuse. Investigate certificate warnings rather than ignoring them.'),
[b('Leia a URL completa','Read the complete URL'),b('Separe host e caminho','Separate host and path'),b('Verifique conexão e certificado','Check connection and certificate'),b('Confirme origem e finalidade','Verify origin and purpose')],
b('O que HTTPS protege e o que ele não comprova?','What does HTTPS protect and what does it not prove?'),b('Protege dados em trânsito e verifica o certificado do destino. Não comprova honestidade, autorização do pedido ou segurança de todo arquivo.','It protects data in transit and verifies the destination certificate. It does not prove honesty, request authorization or every file’s safety.'),
b('Com VPN e modo anônimo, você pode enviar sua senha a qualquer página HTTPS?','With VPN and private browsing, can you send your password to any HTTPS page?'),b('Não. Esses recursos não corrigem destino errado ou pedido fraudulento. Confira host, origem e necessidade do pedido pelo canal oficial.','No. They do not fix a wrong destination or fraudulent request. Check host, origin and necessity through the official channel.')),
m4:unit(
b('Privacidade começa na finalidade: para que este dado é necessário? Depois vêm minimização, acesso e prazo. Dados pessoais podem identificar alguém direta ou indiretamente. Tirar o nome não apaga combinações que identificam uma pessoa. Uma planilha útil para uma tarefa pode ser excessiva para outra; compartilhar exige revisar conteúdo e destinatários.','Privacy starts with purpose: why is this data needed? Then come minimization, access and retention. Personal data can identify someone directly or indirectly. Removing names does not remove identifying combinations. A useful sheet for one task may be excessive for another; sharing requires reviewing content and recipients.'),
b('Para organizar uma feira, você recebe nomes, turma, contato e informação de saúde dos alunos. O voluntário só precisa saber quem atende cada horário. Deve receber a planilha inteira?','To organize a fair, you receive names, class, contact and student health information. A volunteer only needs to know who staffs each time slot. Should they receive the entire sheet?'),
b('Não: prepare uma visão com os dados necessários para a escala e limite o acesso ao grupo responsável. Informação de saúde não ajuda a distribuir horários. Defina prazo e remoção conforme o processo da escola. Finalidade, necessidade e público são decisões diferentes.','No: prepare a view containing necessary scheduling data and limit access to the responsible group. Health information does not help allocate time slots. Define retention and deletion through the school process. Purpose, necessity and audience are separate decisions.'),
b('Não conclua que um arquivo é anônimo só porque não tem nomes. Nem todo compartilhamento interno é necessário ou permitido; siga o processo de privacidade responsável.','Do not conclude a file is anonymous because names are absent. Not every internal disclosure is necessary or permitted; follow the responsible privacy process.'),
[b('Defina a finalidade','Define purpose'),b('Selecione apenas o necessário','Select only what is needed'),b('Limite público e prazo','Limit audience and retention'),b('Revise o compartilhamento','Review sharing')],
b('Por que retirar nomes pode não anonimizar uma tabela?','Why might removing names fail to anonymize a table?'),b('Outros atributos, como turma, idade e evento raro, podem identificar alguém quando combinados. É preciso avaliar o risco de reidentificação no contexto.','Other attributes, such as class, age and a rare event, may identify someone in combination. Assess contextual reidentification risk.'),
b('Um colega solicita todos os contatos para “talvez usar depois”. Como você responde?','A colleague requests all contacts to “perhaps use later”. How do you respond?'),b('Peço finalidade e necessidade claras, verifico o processo aplicável e ofereço somente os dados necessários ao público autorizado. Possível uso futuro não justifica coleta indiscriminada.','Ask for clear purpose and necessity, check the applicable process and provide only necessary data to authorized recipients. Possible future use does not justify indiscriminate collection.')),
m5:unit(
b('Malware é software que realiza ações prejudiciais; pode chegar como anexo, macro ou instalador convincente. Execução, permissões e comunicação são partes do caminho. Atualização e proteção reduzem exposição, mas suspeita exige resposta: conter a propagação, comunicar e preservar o que ajuda a investigar. Contenção não é a mesma coisa que apagar o problema.','Malware is software that performs harmful actions; it can arrive as an attachment, macro or convincing installer. Execution, permissions and communication form part of the path. Updates and protection reduce exposure, but suspicion needs containment, communication and preserved evidence. Containment is different from deleting the problem.'),
b('Um anexo de “boletim” pede para habilitar macros. Depois de aberto, arquivos ficam inacessíveis. Você pensa em conectar o disco de backup para recuperar imediatamente.','A “report card” attachment asks you to enable macros. After opening it, files become inaccessible. You consider connecting the backup drive for immediate recovery.'),
b('Conectar o backup ao dispositivo suspeito pode expor também a cópia. Interrompa o acesso à rede conforme orientação da equipe, comunique o incidente e preserve informações de horário, mensagem e sintomas. A recuperação deve usar um ambiente confiável e um procedimento validado.','Connecting the backup to the suspect device can expose the copy too. Contain network access following team guidance, report the incident and preserve time, message and symptoms. Recovery should use a trusted environment and a validated procedure.'),
b('Um computador lento não prova infecção. Evite medidas improvisadas que destruam evidências; desligamento e coleta dependem do contexto e do procedimento da equipe.','A slow computer does not prove infection. Avoid improvised steps that destroy evidence; shutdown and collection depend on context and team procedure.'),
[b('Arquivo tenta ser executado','File attempts execution'),b('Sintomas levantam uma hipótese','Symptoms raise a hypothesis'),b('Equipe contém e preserva evidências','Team contains and preserves evidence'),b('Recuperação usa ambiente confiável','Recovery uses a trusted environment')],
b('Explique a diferença entre conter e recuperar um incidente.','Explain the difference between containing and recovering an incident.'),b('Conter limita propagação e impacto. Recuperar restaura operação confiável depois de tratar a causa e verificar o ambiente. Uma ação não substitui a outra.','Containment limits spread and impact. Recovery restores trustworthy operation after addressing cause and checking the environment. One does not replace the other.'),
b('O antivírus não alertou, mas um arquivo pediu macros inesperadas. Isso libera a execução?','Antivirus did not alert, but a file requested unexpected macros. Does that authorize execution?'),b('Não. Ausência de alerta não prova segurança. Verifique origem e necessidade pelo processo autorizado, sem executar para “ver o que acontece”.','No. No alert does not prove safety. Verify origin and necessity through the authorized process rather than executing to “see what happens”.')),
m6:unit(
b('No celular, cada permissão abre um tipo de acesso: localização, câmera, contatos ou acessibilidade. A pergunta é se o acesso combina com a função, quando é usado e quem o recebe. Bloqueio de tela e atualizações protegem outras camadas. Configurar recuperação e bloqueio remoto antes de perder o aparelho aumenta suas opções depois.','On a phone, each permission opens a type of access: location, camera, contacts or accessibility. Ask whether access fits the function, when it is used and who receives it. Screen lock and updates protect other layers. Setting recovery and remote lock before loss increases later options.'),
b('Um aplicativo de lanterna pede seus contatos e acesso de acessibilidade. Você só quer iluminar um corredor. Qual relação existe entre a tarefa e esses acessos?','A flashlight app asks for contacts and accessibility access. You only want to light a hallway. How do those permissions relate to the task?'),
b('Esses acessos não parecem necessários à lanterna. Negue o que não atende à função, confira origem e alternativas e evite manter aplicativos desnecessários. Permissão de acessibilidade pode permitir ações amplas; não a conceda só porque uma tela pede.','Those permissions do not appear necessary for a flashlight. Deny access unrelated to the function, check origin and alternatives and avoid unnecessary apps. Accessibility access can enable broad actions; do not grant it merely because a screen asks.'),
b('Uma loja oficial reduz alguns riscos, mas não dispensa avaliar permissões e comportamento. Bloqueio remoto exige configuração e condições de conectividade; não garante recuperar o aparelho.','An official store reduces some risks but does not remove permission and behavior checks. Remote locking requires setup and connectivity conditions; it does not guarantee device recovery.'),
[b('Aplicativo apresenta uma função','App offers a function'),b('Você compara permissões e necessidade','Compare permissions and necessity'),b('Concede apenas o acesso necessário','Grant only necessary access'),b('Revê acessos e prepara recuperação','Review access and prepare recovery')],
b('Por que permissões devem ser avaliadas pela função do aplicativo?','Why evaluate permissions against the app function?'),b('Cada acesso aumenta o que o app pode observar ou fazer. O necessário para a tarefa pode ser menor que o solicitado; origem conhecida não elimina essa avaliação.','Each permission increases what the app can observe or do. The task may need less than the request; a known origin does not eliminate this evaluation.'),
b('Um app de mapas precisa de localização só durante a viagem. Qual escolha merece comparação?','A maps app needs location only during a trip. Which choice should you compare?'),b('Compare acesso durante o uso com acesso permanente. Prefira o escopo que atende à tarefa e revise as configurações; confirme se a função realmente precisa operar em segundo plano.','Compare while-in-use with permanent access. Prefer the scope that meets the task and review settings; check whether the function truly needs background operation.')),
m7:unit(
b('Backup é uma cópia planejada para recuperação. Sincronização replica mudanças e pode replicar exclusões ou corrupção. Separação protege a cópia contra uma falha comum; integridade verifica conteúdo; teste de restauração verifica se dados, chaves e dependências realmente voltam a funcionar. Uma cópia existente pode ser inútil se você não conseguir acessá-la.','A backup is a copy planned for recovery. Sync replicates changes, including deletion or corruption. Separation protects against shared failure; integrity checks content; restoration testing checks whether data, keys and dependencies actually work. An existing copy can be useless if you cannot access it.'),
b('Você apaga uma pasta por engano e a mudança aparece na nuvem sincronizada. Há também uma cópia desconectada feita ontem. Qual delas oferece um ponto de recuperação independente?','You accidentally delete a folder and sync repeats the change in the cloud. There is also a disconnected copy from yesterday. Which offers an independent recovery point?'),
b('A cópia de ontem pode preservar o estado anterior, desde que seja íntegra e acessível. Verifique a data, restaure primeiro em um local de teste e confira arquivos e dependências. Você pode perder alterações posteriores: por isso frequência e tempo de recuperação precisam ser planejados.','Yesterday’s copy may preserve the previous state if intact and accessible. Check its date, restore to a test location first and verify files and dependencies. Later changes may be lost, so frequency and recovery time need planning.'),
b('Histórico de versões pode ajudar, mas depende do serviço, da retenção e do acesso. “Está na nuvem” não comprova independência nem capacidade de restaurar.','Version history may help but depends on service, retention and access. “It is in the cloud” does not prove independence or restoration ability.'),
[b('Defina o que precisa voltar','Define what must return'),b('Crie cópias separadas e protegidas','Create separate protected copies'),b('Teste dados, chaves e dependências','Test data, keys and dependencies'),b('Meça o resultado da restauração','Measure restoration outcome')],
b('Qual diferença separa sincronizar de fazer backup?','What separates synchronization from backup?'),b('Sincronizar mantém estados alinhados e pode copiar uma falha. Backup preserva pontos de recuperação segundo uma política. Um serviço pode oferecer ambos, mas é preciso verificar.','Sync aligns states and can copy a failure. Backup preserves recovery points under a policy. A service may offer both, but you must verify.'),
b('O arquivo de backup abre, mas o sistema não inicia sem uma chave perdida. O teste passou?','The backup file opens, but the system cannot start without a lost key. Did the test pass?'),b('Não. Recuperação inclui acesso, chaves e dependências, além dos bytes. O teste deve demonstrar a operação necessária, não apenas a existência do arquivo.','No. Recovery includes access, keys and dependencies as well as bytes. The test must demonstrate the needed operation, not just file existence.')),
m8:unit(
b('DNS consulta registros associados a nomes; IP endereça o destino; protocolo e porta distinguem serviços. Pense em nome, endereço e setor de atendimento, sem confundir os três. Uma conexão pode falhar em etapas diferentes: resolução, rota, serviço ou validação TLS. Diagnosticar é localizar a etapa com evidências, não trocar tudo de uma vez.','DNS queries records associated with names; IP addresses the destination; protocol and port distinguish services. Think of name, address and service desk without confusing them. A connection may fail at resolution, route, service or TLS validation. Diagnosis locates the failing stage with evidence rather than changing everything.'),
b('O portal da escola não abre. O nome resolve para um IP, mas o serviço TCP/443 não responde. Um colega diz que “o DNS está quebrado”. O resultado sustenta essa conclusão?','The school portal does not open. Its name resolves to an IP, but TCP/443 does not respond. A colleague says “DNS is broken”. Does the result support that conclusion?'),
b('A consulta teve uma resposta; isso não prova que seja a resposta correta, mas não sustenta sozinho falha de resolução. Confira destino esperado, horário e alcance do serviço. A porta identifica um ponto de atendimento; não prova confiança ou identidade.','The query returned an answer; that does not prove it is correct, but alone it does not show resolution failure. Check expected destination, time and service reachability. A port identifies a service endpoint, not trust or identity.'),
b('Um serviço pode usar porta diferente da convencional. DNS resolvido e conexão aberta também não garantem que o usuário esteja autorizado.','A service can use a nonstandard port. Resolved DNS and an open connection also do not guarantee user authorization.'),
[b('Nome é consultado no DNS','Name is queried in DNS'),b('Resposta indica um endereço','Response indicates an address'),b('Protocolo e porta apontam o serviço','Protocol and port identify the service'),b('Resultado é comparado ao esperado','Result is compared with expectations')],
b('Explique as funções de DNS, IP e porta sem tratar nenhum como prova de confiança.','Explain DNS, IP and port without treating any as proof of trust.'),b('DNS consulta nomes e registros, IP endereça comunicação e porta junto ao protocolo distingue serviços. Identidade, autorização e finalidade exigem verificações próprias.','DNS queries names and records, IP addresses communication and port with protocol distinguishes services. Identity, authorization and purpose need separate checks.'),
b('O portal responde em 443 com alerta de certificado. Como isso muda a investigação?','The portal responds on 443 with a certificate warning. How does that change the investigation?'),b('Há alcance do serviço, mas a validação da conexão tem um problema. Confira destino e contexto e reporte; não ignore o alerta para “resolver a rede”.','The service is reachable but connection validation has a problem. Check destination and context and report it; do not ignore the warning to “fix the network”.')),
m9:unit(
b('Cifragem transforma dados com uma chave para proteger conteúdo; decifragem recupera o texto autorizado. Hash produz um resumo para comparar bytes, sem ser uma cifra reversível. Assinatura usa a chave privada do autor e é verificada com sua pública: relaciona conteúdo à chave, mas depende de confiar nessa chave e no contexto.','Encryption transforms data using a key to protect content; decryption recovers authorized plaintext. A hash produces a digest for comparing bytes and is not reversible encryption. A signature uses the author’s private key and their public key for verification; trust in that key and context remains necessary.'),
b('Você baixa um arquivo e compara seu hash com outro número escrito na mesma página desconhecida. A comparação coincide. Isso prova que o programa é confiável?','You download a file and compare its hash with a number on the same unknown page. They match. Does that prove the program is trustworthy?'),
b('A coincidência indica que os bytes correspondem à referência, mas a referência também pode ter sido escolhida por quem publicou o arquivo. Procure uma fonte confiável e verificação apropriada. Integridade, confidencialidade e origem são perguntas distintas; um mecanismo não responde automaticamente às três.','The match indicates bytes agree with the reference, but the publisher could have chosen both. Use a trusted source and suitable verification. Integrity, confidentiality and origin are separate questions; one mechanism does not automatically answer all three.'),
b('A cifra de deslocamento da bancada é um modelo didático, não proteção moderna. Não invente algoritmos ou use os exemplos para guardar dados reais.','The shift cipher on the desk is a teaching model, not modern protection. Do not invent algorithms or use the examples to protect real data.'),
[b('Defina o objetivo de proteção','Define the protection goal'),b('Escolha cifra, hash ou assinatura','Choose encryption, hash or signature'),b('Use chave e referência adequadas','Use a suitable key and reference'),b('Verifique resultado e confiança','Verify outcome and trust')],
b('Qual chave assina e qual verifica? Isso também esconde a mensagem?','Which key signs and which verifies? Does that also hide the message?'),b('A privada do autor assina; a pública correspondente verifica. A assinatura por si só não oferece confidencialidade: para esconder conteúdo, é necessário um mecanismo de cifragem adequado.','The author’s private key signs; the corresponding public key verifies. Signing alone does not provide confidentiality; hiding content requires suitable encryption.'),
b('Um arquivo alterado mantém o nome e tamanho. O hash necessariamente continua igual?','An altered file keeps its name and size. Must its hash remain the same?'),b('Não. O hash é calculado sobre os bytes, não apenas nome ou tamanho. A comparação precisa usar o mesmo algoritmo e uma referência confiável.','No. Hashes are computed over bytes, not just name or size. Comparison needs the same algorithm and a trusted reference.')),
m10:unit(
b('Permissão responde quem pode fazer qual ação sobre um recurso. Leitura, escrita e execução são diferentes. No modelo Linux simplificado, dono, grupo e outros são classes; no Windows, grupos e herança contribuem para o acesso efetivo. Conceder o mínimo necessário exige testar tanto a tarefa permitida quanto uma tarefa que deve ser negada.','Permission asks who may perform which action on a resource. Read, write and execute differ. In the simplified Linux model, owner, group and others are classes; on Windows, groups and inheritance contribute to effective access. Least privilege needs both allowed-task and denied-task tests.'),
b('Uma equipe precisa ler relatórios, mas só a coordenadora deve editá-los. Para resolver uma falha de acesso, alguém oferece escrita a todos. O que essa mudança realmente altera?','A team needs to read reports, but only the coordinator should edit them. To fix an access issue, someone offers write access to everyone. What does that really change?'),
b('Ela amplia a capacidade de alterar o conteúdo para pessoas que só deveriam ler. Identifique a conta e o grupo responsáveis, conceda leitura à equipe e escrita apenas a quem precisa. Teste uma leitura autorizada e uma edição negada, incluindo permissões herdadas.','It lets people who should only read alter content. Identify the responsible account and group, grant team read access and write only where needed. Test authorized reading and denied editing, including inherited permissions.'),
b('A bancada simplifica o sistema. Acesso efetivo real pode envolver ACLs, herança e outros controles; não conclua a permissão só pelo rótulo de um grupo.','The desk simplifies the system. Real effective access can involve ACLs, inheritance and other controls; do not conclude permission from a group label alone.'),
[b('Identifique pessoa e recurso','Identify person and resource'),b('Defina a ação necessária','Define the required action'),b('Conceda o menor acesso suficiente','Grant the least sufficient access'),b('Teste permissão e negação','Test permission and denial')],
b('Por que testar só o acesso permitido é incompleto?','Why is testing only allowed access incomplete?'),b('Demonstra que a tarefa funciona, mas não que acessos desnecessários foram impedidos. Um teste negativo confirma uma restrição relevante.','It shows the task works, but not that unnecessary access is prevented. A negative test checks a relevant restriction.'),
b('Uma conta não tem escrita direta, mas pertence a outro grupo com escrita. Pode editar?','An account lacks direct write permission but belongs to another group with write access. Can it edit?'),b('Pode, dependendo do cálculo de acesso efetivo do sistema. Avalie os grupos, a herança e as regras aplicáveis antes de concluir.','Possibly, depending on the system’s effective access calculation. Evaluate groups, inheritance and applicable rules before concluding.')),
m11:unit(
b('Um comando combina operação, caminho e parâmetros. O contexto importa: pasta atual e privilégios mudam o alcance de uma ação. Em PowerShell, LiteralPath trata o caminho como literal, evitando interpretar caracteres como padrões. Um script confiável também distingue sucesso e falha, limita privilégios e só anuncia conclusão quando a operação terminou.','A command combines operation, path and parameters. Context matters: current directory and privileges change its scope. In PowerShell, LiteralPath treats the path literally instead of interpreting pattern characters. A reliable script distinguishes success and failure, limits privileges and reports completion only after the operation finishes.'),
b('Você quer copiar o arquivo relatorio[1].txt. Um comando interpreta os colchetes como parte de um padrão e encontra outro arquivo. O nome visível parecia exato, mas o resultado não foi.','You want to copy relatorio[1].txt. A command treats brackets as part of a pattern and finds another file. The visible name seemed exact, but the outcome was not.'),
b('Confira a pasta, o caminho completo e a opção LiteralPath do comando que a suporta. Antes de uma operação ampla, liste o alvo e teste com dados de laboratório. No script, registre falhas e retorne um resultado coerente; imprimir “sucesso” antes de verificar não comprova a cópia.','Check the directory, full path and LiteralPath option on commands that support it. Before a broad operation, inspect targets and test with lab data. Record failures and return consistent results; printing “success” before checking does not prove the copy.'),
b('Nem todos os comandos usam os mesmos parâmetros. O terminal do jogo é simulado; não copie comandos para um sistema real sem entender alvos e efeitos.','Commands do not all use identical parameters. The game terminal is simulated; do not copy commands to a real system without understanding targets and effects.'),
[b('Confira contexto e caminho','Check context and path'),b('Leia operação e parâmetros','Read operation and parameters'),b('Execute o teste autorizado','Run the authorized test'),b('Verifique resultado e falhas','Check result and failures')],
b('Qual problema LiteralPath ajuda a evitar?','What problem does LiteralPath help avoid?'),b('Ajuda a evitar que caracteres de um nome sejam interpretados como curingas. Não verifica sozinho se o caminho é correto, autorizado ou seguro.','It helps prevent name characters from being interpreted as wildcards. It does not itself verify the path is correct, authorized or safe.'),
b('O script mostra “concluído”, mas a operação anterior falhou. O que precisa mudar?','The script says “complete”, but the previous operation failed. What must change?'),b('A mensagem e o resultado precisam depender da operação verificada. Trate a falha, interrompa passos dependentes quando necessário e não anuncie sucesso indevido.','The message and result must depend on the verified operation. Handle failure, stop dependent steps where needed and do not falsely announce success.')),
m12:unit(
b('Autenticação identifica a sessão; autorização decide o acesso permitido. Sessão, consentimento do app e tokens são controles relacionados, mas distintos. Access token chega ao recurso para uma ação; ID token comunica identidade ao cliente; refresh token pode obter novos tokens. Finalidade, destinatário, escopo e validade precisam combinar com o pedido.','Authentication identifies a session; authorization decides allowed access. Session, app consent and tokens are related but distinct controls. An access token reaches a resource for an action; an ID token communicates identity to a client; a refresh token can obtain new tokens. Purpose, audience, scope and validity must match the request.'),
b('Você sai do portal e acha que o aplicativo de calendário perdeu acesso aos seus dados. Porém a autorização concedida ao aplicativo continua na lista de integrações.','You sign out of a portal and think a calendar app lost access to your data. However, its authorization remains in the integrations list.'),
b('Sair encerra uma sessão segundo o serviço, mas não necessariamente revoga a autorização do aplicativo. Use os controles oficiais para revisar integrações e revogar o consentimento quando necessário. Confira também sessões e outros acessos: cada controle resolve uma parte do problema.','Signing out ends a session according to the service, but does not necessarily revoke app authorization. Use official controls to review integrations and revoke consent where needed. Also check sessions and other access: each control addresses part of the problem.'),
b('Os cartões da aula comparam metadados fictícios; não validam assinaturas JWT. Um token vigente ainda pode ser destinado a outro recurso ou ter escopo insuficiente.','Lesson cards compare fictional metadata; they do not validate JWT signatures. A live token can still target another resource or have insufficient scope.'),
[b('Usuário inicia uma sessão','User starts a session'),b('Aplicativo recebe acesso delimitado','App receives bounded access'),b('Recurso verifica finalidade e permissão','Resource checks purpose and permission'),b('Revogação trata o acesso correspondente','Revocation handles the matching access')],
b('Por que um ID token não deve substituir um access token para uma API?','Why should an ID token not replace an API access token?'),b('As finalidades e destinatários diferem. Identidade comunicada ao cliente não é a autorização exigida pelo recurso; a API deve validar o token apropriado ao pedido.','Purposes and audiences differ. Identity communicated to a client is not the resource’s required authorization; the API must validate the appropriate token.'),
b('O token tem escopo de leitura, mas a operação quer apagar um arquivo. Basta estar vigente?','A token has read scope, but the operation wants to delete a file. Is being live sufficient?'),b('Não. Prazo, destinatário e escopo precisam atender à ação, além das outras verificações. Uma condição correta não compensa uma permissão ausente.','No. Validity, audience and scope must match the action along with other checks. One correct condition does not compensate for missing permission.')),
m13:unit(
b('SPF avalia a origem autorizada para a identidade de envelope; DKIM verifica uma assinatura associada a um domínio. DMARC relaciona essas verificações ao domínio do From visível: basta SPF aprovado e alinhado OU DKIM aprovado e alinhado. Isso trata autenticação de domínio, não honestidade de toda mensagem.','SPF evaluates authorized origin for the envelope identity; DKIM verifies a signature associated with a domain. DMARC relates these checks to the visible From domain: aligned passing SPF OR aligned passing DKIM is sufficient. This addresses domain authentication, not every message’s honesty.'),
b('Uma mensagem tem From escola.example. SPF passa para outro.example, sem alinhamento. DKIM passa e se alinha com escola.example. DMARC precisa reprovar porque SPF não se alinhou?','A message has From escola.example. SPF passes for outro.example without alignment. DKIM passes and aligns with escola.example. Must DMARC fail because SPF is not aligned?'),
b('Não: nesse modelo, DKIM aprovado e alinhado já fornece um caminho válido. O operador é OU, não E. Em seguida avalie conteúdo, pedido e contexto; uma conta ou serviço legítimo pode enviar um pedido perigoso.','No: in this model, aligned passing DKIM provides a valid path. The operator is OR, not AND. Then evaluate content, request and context; a legitimate account or service can send a dangerous request.'),
b('A bancada simplifica regras de alinhamento. DMARC pass não significa “pode clicar em tudo”, e fail isolado exige investigação do fluxo e da política aplicada.','The desk simplifies alignment rules. DMARC pass does not mean “click everything”, and isolated failure needs investigation of the flow and applied policy.'),
[b('Leia o From visível','Read the visible From'),b('Confira SPF e seu alinhamento','Check SPF and its alignment'),b('Confira DKIM e seu alinhamento','Check DKIM and its alignment'),b('Combine com OU e avalie o conteúdo','Combine using OR and assess content')],
b('Recupere de memória a condição de DMARC pass.','Recall the DMARC pass condition from memory.'),b('SPF passa e alinha com o From, ou DKIM passa e alinha com o From. Passar sem alinhamento não basta nesse caminho.','SPF passes and aligns with From, or DKIM passes and aligns with From. Passing without alignment is insufficient for that path.'),
b('DMARC passa, mas o texto pede um código de login. O que você conclui?','DMARC passes, but the text asks for a login code. What do you conclude?'),b('A autenticação de domínio passou; o pedido ainda deve ser avaliado. Não compartilhe o código e confirme pelo canal conhecido. Autenticação de origem não é autorização do pedido.','Domain authentication passed; the request still needs evaluation. Do not share the code; verify through a known channel. Origin authentication is not request authorization.')),
m14:unit(
b('Na nuvem, público define quem pode chegar ao recurso; identidade diferencia pessoas; papel determina ações; prazo limita a concessão. A responsabilidade varia conforme o serviço: o provedor opera certas camadas, enquanto o cliente ainda configura acessos e cuida dos dados sob seu controle. Um link não é automaticamente uma autorização adequada.','In cloud services, audience defines who can reach a resource; identity distinguishes people; role determines actions; expiry limits the grant. Responsibility varies by service: the provider operates certain layers while the customer configures access and handles data under their control. A link is not automatically suitable authorization.'),
b('Você compartilha um trabalho com “qualquer pessoa com o link” e papel de editor. Só precisava da leitura pelo professor durante uma semana. Quais dimensões ficaram amplas demais?','You share homework with “anyone with the link” and editor role. You only needed the teacher to read it for a week. Which dimensions were too broad?'),
b('O público inclui pessoas não previstas e o papel permite alterações. Restrinja à identidade apropriada, leitura e prazo necessário. Teste com quem deve acessar e com quem não deve. Revisar apenas o nome do arquivo não muda essas permissões.','The audience includes unintended people and the role permits changes. Restrict to the appropriate identity, read access and needed duration. Test with allowed and denied users. Reviewing only the filename does not change those permissions.'),
b('O modelo de link da aula é uma concessão única. Serviços reais podem combinar outros acessos, grupos e heranças; confira o acesso efetivo.','The lesson link model is a single grant. Real services may combine other access, groups and inheritance; check effective access.'),
[b('Escolha o público','Choose the audience'),b('Defina a identidade e o papel','Define identity and role'),b('Limite a duração','Limit duration'),b('Teste acesso permitido e negado','Test allowed and denied access')],
b('Público, papel e prazo respondem às mesmas perguntas?','Do audience, role and expiry answer the same questions?'),b('Não. Público responde quem; papel, quais ações; prazo, até quando. Uma configuração restrita em uma dimensão não corrige as outras.','No. Audience asks who; role asks which actions; expiry asks until when. Restriction in one dimension does not fix the others.'),
b('O link expirou, mas alguém copiou os dados antes. A cópia desaparece?','The link expired, but someone previously copied the data. Does the copy disappear?'),b('Não. Expiração limita o acesso futuro pela concessão; não desfaz cópias já obtidas. Por isso avalie conteúdo e destinatários antes de compartilhar.','No. Expiry limits future access through the grant; it does not undo previously obtained copies. Assess content and recipients before sharing.')),
m15:unit(
b('Segmentação divide caminhos e reduz comunicação desnecessária. Uma regra de firewall compara origem, destino, protocolo e porta; a política deve seguir a necessidade da tarefa. Em um firewall com estado, retorno de uma conexão reconhecida não equivale a permitir qualquer conexão nova no sentido inverso. Zona de rede não identifica sozinha uma pessoa.','Segmentation divides paths and reduces unnecessary communication. A firewall rule compares source, destination, protocol and port; policy should follow task needs. In a stateful firewall, recognized return traffic does not permit every new reverse-direction connection. A network zone does not alone identify a person.'),
b('Alunos precisam abrir o portal em TCP/443, mas não administrar o servidor em TCP/22. Uma regra permite a rede dos alunos para qualquer serviço do servidor.','Students need the portal on TCP/443, but not server administration on TCP/22. A rule permits the student network to every server service.'),
b('A regra atende ao portal e também abre um caminho não necessário. Restrinja destino, protocolo e porta conforme a política, depois teste portal permitido e administração negada. A aplicação ainda precisa autorizar usuários e recursos; firewall não substitui essa camada.','The rule allows the portal and opens an unnecessary path. Restrict destination, protocol and port under the policy, then test allowed portal access and denied administration. The application must still authorize users and resources; a firewall does not replace that layer.'),
b('A simulação representa um conjunto pequeno de regras. Topologias reais incluem ordem, NAT, estado e outras políticas que precisam ser verificadas.','The simulation represents a small rule set. Real topologies include order, NAT, state and other policies that need checking.'),
[b('Leia a tarefa esperada','Read the expected task'),b('Compare os quatro campos da regra','Compare the rule’s four fields'),b('Decida sobre conexão nova ou retorno','Distinguish new connection from return'),b('Teste os dois lados da política','Test both sides of the policy')],
b('Que quatro campos você compara numa regra deste laboratório?','Which four fields do you compare in this lab rule?'),b('Origem, destino, protocolo e porta. Também verifique a direção e se é conexão nova ou retorno reconhecido no modelo.','Source, destination, protocol and port. Also check direction and whether it is a new connection or recognized return in the model.'),
b('O retorno do servidor passou. Um novo acesso do servidor ao aluno está automaticamente liberado?','Server return traffic passed. Is a new server-to-student connection automatically allowed?'),b('Não. O estado reconhece uma comunicação já autorizada, não toda iniciativa no sentido inverso. A nova conexão deve ser avaliada pela política.','No. State recognizes an already authorized communication, not every reverse-direction initiation. The new connection must be assessed against policy.')),
m16:unit(
b('Investigar é ligar fatos sem transformar proximidade em causalidade. Um registro descreve um evento conforme a fonte; sessão, ação e resultado ajudam a correlacionar. Horários exigem fuso e confiança no relógio. Preserve o original e crie uma linha do tempo normalizada para comparar. Hipóteses devem mostrar também lacunas e explicações alternativas.','Investigation links facts without turning proximity into causality. A record describes an event according to its source; session, action and result aid correlation. Times need timezone and clock confidence. Preserve originals and create a normalized timeline. Hypotheses should include gaps and alternative explanations.'),
b('Um login aparece às 09:01 UTC−03 e um download às 12:02 UTC. Alguém diz que ocorreram com três horas de diferença.','A login appears at 09:01 UTC−03 and a download at 12:02 UTC. Someone says they occurred three hours apart.'),
b('09:01 UTC−03 corresponde a 12:01 UTC: a distância é um minuto, se os relógios forem confiáveis. Ainda não prova a mesma atividade. Compare sessão, identidade observada e resultado; mantenha a marca original junto da conversão para poder revisar.','09:01 UTC−03 is 12:01 UTC: the gap is one minute if clocks are reliable. That still does not prove one activity. Compare session, observed identity and result; retain the original timestamp alongside the conversion for review.'),
b('Conta não é autoria pessoal. Falta de log não prova falta de evento; cobertura, retenção e sincronização podem limitar a visão.','An account is not personal attribution. Missing logs do not prove no event; coverage, retention and synchronization can limit visibility.'),
[b('Preserve a fonte original','Preserve the original source'),b('Normalize horário sem perder o fuso','Normalize time without losing timezone'),b('Correlacione sessão, ação e resultado','Correlate session, action and result'),b('Separe fato, hipótese e lacuna','Separate fact, hypothesis and gap')],
b('Como converter 09:01 UTC−03 para UTC?','How do you convert 09:01 UTC−03 to UTC?'),b('Some três horas: 12:01 UTC. Registre o fuso original e confira a confiança no relógio antes de ordenar eventos.','Add three hours: 12:01 UTC. Record the original timezone and assess clock confidence before ordering events.'),
b('Dois eventos próximos usam a mesma conta, mas sessões diferentes. Já provam uma sequência única?','Two nearby events use the same account but different sessions. Do they prove one sequence?'),b('Não. É preciso correlacionar outros campos e considerar atividades paralelas. Relate o que foi observado e qual ligação ainda é hipótese.','No. Correlate other fields and consider parallel activity. Report what was observed and which connection remains hypothetical.')),
m17:unit(
b('Processo é um programa em execução com contexto e recursos; threads são linhas de execução dentro dele. Serviços realizam tarefas, muitas vezes sem uma janela visível. A conta e os privilégios delimitam acesso. Nome e uso de CPU não comprovam legitimidade; compare origem, finalidade, pai, conta e comportamento esperado.','A process is a running program with context and resources; threads are execution paths inside it. Services perform tasks, often without a visible window. Account and privileges delimit access. Name and CPU usage do not prove legitimacy; compare origin, purpose, parent, account and expected behavior.'),
b('O serviço de notas só precisa ler uma pasta de entrada e gravar relatórios numa saída. Está usando uma conta administrativa que também pode alterar as notas originais.','A grading service only needs to read an input folder and write reports to output. It uses an administrator account that can also change the original grades.'),
b('Uma conta dedicada com leitura na entrada e escrita na saída atende à tarefa com menor alcance. Teste a geração do relatório e confirme que alterações nas notas e na entrada são negadas. Não basta o serviço funcionar: ele precisa funcionar dentro dos limites definidos.','A dedicated account with input read and output write access meets the task with less reach. Test report generation and confirm grade and input modifications are denied. It must work within defined limits, not merely work.'),
b('Modo usuário/kernel é uma separação de execução, não um selo de segurança. Diagnóstico real envolve detalhes do sistema e evidências adicionais.','User/kernel mode separates execution; it is not a safety seal. Real diagnosis involves system details and additional evidence.'),
[b('Identifique processo e finalidade','Identify process and purpose'),b('Examine contexto e conta','Examine context and account'),b('Limite recursos e ações','Limit resources and actions'),b('Teste comportamento e restrições','Test behavior and restrictions')],
b('Qual é a diferença entre processo e thread?','What is the difference between process and thread?'),b('Um processo tem contexto e recursos; threads executam dentro desse contexto e compartilham recursos do processo. O nome do processo não prova a sua origem.','A process has context and resources; threads execute within it and share process resources. A process name does not prove its origin.'),
b('Um processo chamado “Atualizador” usa pouca CPU. Isso basta para autorizá-lo?','A process called “Updater” uses little CPU. Is that sufficient to authorize it?'),b('Não. Compare origem, finalidade, conta e comportamento com o esperado. Nome convincente e baixa CPU não comprovam legitimidade.','No. Compare origin, purpose, account and behavior with expectations. A convincing name and low CPU do not prove legitimacy.')),
m18:unit(
b('Uma assinatura liga conteúdo a uma chave privada; verificar exige a chave pública correspondente. Um certificado pode relacionar essa chave a uma identidade segundo uma cadeia de confiança e uma finalidade. Validade temporal, revogação e contexto importam. HTTPS do download e assinatura do documento são verificações separadas.','A signature links content to a private key; verification needs the corresponding public key. A certificate can relate that key to an identity under a trust chain and purpose. Time validity, revocation and context matter. Download HTTPS and document signing are separate checks.'),
b('Você recebe um documento por HTTPS. A assinatura matemática confere, mas o certificado do assinante foi revogado e não há carimbo de tempo confiável para avaliar uma assinatura anterior.','You receive a document over HTTPS. The mathematical signature verifies, but the signer certificate is revoked and there is no trusted timestamp for assessing an earlier signature.'),
b('Não trate “verificou” como aprovação completa. O modelo exige considerar confiança e estado no dia consultado; registre o resultado e investigue o contexto. A conexão protegida não resolve a confiança no documento. Se houver comprometimento de chave, rotação não apaga usos anteriores.','Do not treat “verified” as complete approval. The model requires trust and status on the checked date; record the result and investigate context. A protected connection does not resolve document trust. If a key is compromised, rotation does not erase previous uses.'),
b('A bancada não modela todas as políticas de assinatura histórica. Sistemas reais podem usar carimbo de tempo e regras próprias; não conclua validade passada só pela data escrita no arquivo.','The desk does not model every historical signature policy. Real systems may use trusted timestamps and their own rules; a file’s written date alone does not establish past validity.'),
[b('Confira o conteúdo assinado','Check signed content'),b('Verifique a chave correspondente','Verify the matching key'),b('Avalie cadeia, prazo e revogação','Assess chain, time and revocation'),b('Relate confiança e limites','Report trust and limits')],
b('Por que HTTPS do site não valida a assinatura do documento?','Why does site HTTPS not validate the document signature?'),b('HTTPS protege a conexão com aquele host. A assinatura do documento envolve conteúdo, chave do autor e contexto de confiança próprios.','HTTPS protects the connection to that host. A document signature involves its content, author key and separate trust context.'),
b('Uma chave comprometida foi trocada hoje. Os arquivos assinados ontem ficam automaticamente confiáveis?','A compromised key was replaced today. Are yesterday’s signed files automatically trusted?'),b('Não. Investigue intervalo de comprometimento, evidências e política aplicável. A troca protege usos futuros; não desfaz falsificações ou abuso anteriores.','No. Investigate compromise interval, evidence and applicable policy. Replacement protects future use; it does not undo previous forgery or abuse.')),
m19:unit(
b('Validação define entradas aceitas antes de processar; autorização define quem pode realizar a ação. A tela melhora a experiência, mas o servidor deve impor as regras. Falhas pedem uma resposta pública útil sem detalhes internos e um registro interno controlado, com referência que permita correlacionar. Registre contexto necessário sem despejar senhas ou tokens.','Validation defines accepted inputs before processing; authorization defines who may act. The screen improves usability, but the server must enforce rules. Failures need useful public responses without internals and controlled internal records with a correlation reference. Log needed context without passwords or tokens.'),
b('O formulário permite escolher de uma a três vagas. Uma requisição chega com quantity:12 e o servidor confia que a tela já verificou.','A form allows one to three places. A request arrives with quantity:12 and the server trusts that the screen already checked it.'),
b('O servidor precisa conferir tipo, faixa e opção permitida antes de gravar. Um pedido fora da regra deve ser rejeitado de forma compreensível. Se ocorrer falha ao salvar, relacione mensagem e log por uma referência; dados válidos ainda precisam da autorização adequada.','The server must check type, range and allowed option before writing. Reject out-of-rule requests clearly. If saving fails, relate message and log using a reference; valid data still needs appropriate authorization.'),
b('A bancada usa dados fixos, sem servidor real. Validação de entrada não substitui consultas seguras, tratamento de saída ou autorização.','The desk uses fixed data without a real server. Input validation does not replace safe queries, output handling or authorization.'),
[b('Pedido chega à aplicação','Request reaches the application'),b('Servidor verifica regras e acesso','Server checks rules and access'),b('Operação confirma sucesso ou falha','Operation confirms success or failure'),b('Resposta e log compartilham referência','Response and log share a reference')],
b('Por que validação no navegador é insuficiente?','Why is browser validation insufficient?'),b('Pedidos podem chegar por outros clientes ou sem a checagem da tela. A fronteira de confiança está no servidor que decide processar e gravar.','Requests can arrive through other clients or without screen checks. The trust boundary is the server deciding to process and write.'),
b('O pedido está dentro do limite, mas quer editar o registro de outra pessoa. Pode passar?','The request is within limits but wants to edit someone else’s record. Can it pass?'),b('Validade do dado não concede permissão. Verifique autorização para a identidade, a ação e o objeto antes de modificar.','Valid data does not grant permission. Check authorization for identity, action and object before modifying it.')),
m20:unit(
b('Framework é uma referência para organizar perguntas e decisões. ATT&CK descreve comportamentos adversários; Kill Chain ajuda a discutir etapas de uma cadeia; NIST CSF organiza resultados de gestão de risco; OWASP orienta riscos e controles de aplicações. Escolha conforme o propósito, mantendo fatos, hipóteses e lacunas separados.','A framework organizes questions and decisions. ATT&CK describes adversary behavior; Kill Chain helps discuss chain stages; NIST CSF organizes risk management outcomes; OWASP guides application risks and controls. Choose by purpose while separating facts, hypotheses and gaps.'),
b('Uma equipe viu um comportamento suspeito e quer descrevê-lo; outra precisa definir prioridades de recuperação e gestão. Elas precisam usar exatamente a mesma referência?','One team observed suspicious behavior and wants to describe it; another needs recovery and management priorities. Must they use exactly the same reference?'),
b('Não. ATT&CK pode ajudar a nomear o comportamento observado; CSF pode organizar objetivos de risco e recuperação. As referências podem se complementar. Mapear um evento a uma técnica não prova que ocorreu um ataque; evidências e contexto sustentam a conclusão.','No. ATT&CK can help name observed behavior; CSF can organize risk and recovery objectives. References can complement one another. Mapping an event to a technique does not prove an attack; evidence and context support conclusions.'),
b('Categorias mudam entre versões e não cobrem todas as situações. Uma checklist preenchida não demonstra implementação ou eficácia dos controles.','Categories change across versions and do not cover every situation. A completed checklist does not demonstrate implemented or effective controls.'),
[b('Defina a pergunta da equipe','Define the team question'),b('Escolha a referência apropriada','Choose the appropriate reference'),b('Relacione evidência e categoria','Relate evidence and category'),b('Relate lacunas e próximos testes','Report gaps and next tests')],
b('Qual referência ajuda a descrever comportamento adversário e qual organiza resultados de risco?','Which reference describes adversary behavior and which organizes risk outcomes?'),b('ATT&CK auxilia a descrição de comportamento; NIST CSF organiza resultados de gestão de risco. Eles têm finalidades diferentes e podem se complementar.','ATT&CK assists behavior description; NIST CSF organizes risk management outcomes. They have different purposes and can complement each other.'),
b('Um evento foi mapeado ao ATT&CK. Isso basta para declarar um incidente confirmado?','An event was mapped to ATT&CK. Is that sufficient to declare a confirmed incident?'),b('Não. O mapeamento organiza uma hipótese. Verifique evidências, contexto, alternativas e impacto antes de elevar a conclusão.','No. Mapping organizes a hypothesis. Check evidence, context, alternatives and impact before strengthening the conclusion.')),
m21:unit(
b('SIEM reúne e permite correlacionar registros; um alerta aponta algo a investigar. Triagem compara confiabilidade da evidência, contexto, impacto potencial e urgência. Severidade da ferramenta é uma pista, não uma prioridade automática. Um bom encaminhamento explica fatos observados, hipótese, informação faltante e próxima ação proporcional.','A SIEM collects and correlates records; an alert points to something to investigate. Triage compares evidence reliability, context, potential impact and urgency. Tool severity is a clue, not an automatic priority. A useful handoff explains observed facts, hypothesis, missing information and a proportionate next action.'),
b('Há vinte falhas de login de um teste autorizado e uma exportação bem-sucedida usando uma conta privilegiada em horário incomum. Qual caso merece contexto adicional primeiro?','There are twenty login failures from an authorized test and one successful export using a privileged account at an unusual time. Which case first needs additional context?'),
b('A exportação pode ter maior impacto potencial, mas ainda pode ser legítima. Confira autorização, sessão, recurso e destino; correlacione registros. Quantidade não mede sozinha o risco. Não afirme vazamento ou autoria pessoal apenas porque uma conta aparece.','The export may have greater potential impact, but could still be legitimate. Check authorization, session, resource and destination and correlate records. Count alone does not measure risk. Do not claim a leak or personal attribution just because an account appears.'),
b('Um alerta é uma hipótese operacional. Nem toda exportação indica saída de dados; ausência de evento também pode ser limitação de cobertura.','An alert is an operational hypothesis. Not every export indicates data leaving; missing events may reflect coverage limits.'),
[b('Alerta indica uma observação','Alert indicates an observation'),b('Equipe valida contexto e fonte','Team validates context and source'),b('Impacto orienta prioridade','Impact guides priority'),b('Encaminhamento registra fatos e lacunas','Handoff records facts and gaps')],
b('O que precisa constar em um encaminhamento de triagem útil?','What belongs in a useful triage handoff?'),b('Fatos e fontes, hipótese separada, impacto potencial, lacunas e próxima ação proporcional. Preserve contexto para quem continuará a análise.','Facts and sources, separate hypothesis, potential impact, gaps and a proportionate next action. Preserve context for the next analyst.'),
b('Um alerta tem severidade alta, mas veio de um teste aprovado. Você o apaga sem registrar?','A high-severity alert came from an approved test. Do you delete it without recording?'),b('Não. Confirme escopo e horário do teste, documente a decisão e avalie se há eventos fora do contexto autorizado. Um rótulo de teste não explica automaticamente tudo.','No. Confirm test scope and timing, document the decision and check for events outside the authorized context. A test label does not automatically explain everything.')),
m22:unit(
b('Uma regra de detecção transforma um objetivo em condições sobre dados. Primeiro confira se os campos necessários existem; depois avalie acertos, ruído e casos perdidos. Aumentar o limiar pode reduzir alertas e perder atividade relevante. Uma exceção muito ampla pode ocultar tanto um teste legítimo quanto um uso indevido.','A detection rule turns a goal into data conditions. First check required fields, then evaluate matches, noise and missed cases. Raising the threshold can reduce alerts while missing relevant activity. A broad exception can hide both a legitimate test and misuse.'),
b('Uma regra conta falhas por conta em cinco minutos. Para parar os alertas do laboratório, alguém exclui todos os eventos de um usuário de teste, sem prazo ou filtro de origem.','A rule counts failures per account in five minutes. To stop lab alerts, someone excludes every event from a test user, without expiry or source filtering.'),
b('A exceção pode esconder uso dessa conta fora do teste. Delimite finalidade, origem e prazo quando suportados, documente e reavalie. Teste um exemplo que deve alertar, um legítimo que não deve e um caso sem os campos necessários; “não avaliável” não é “seguro”.','The exception may hide use outside the test. Bound purpose, source and expiry where supported, document and review it. Test an expected alert, a legitimate non-alert and a case missing required fields; “unevaluable” is not “safe”.'),
b('Métricas dependem dos rótulos e da amostra. Bom desempenho em poucos eventos não prova cobertura contra toda atividade futura.','Metrics depend on labels and samples. Good results on a few events do not prove coverage of all future activity.'),
[b('Defina o comportamento procurado','Define the target behavior'),b('Confira campos e janela','Check fields and window'),b('Teste acertos, ruído e perdas','Test matches, noise and misses'),b('Revise exceções e cobertura','Review exceptions and coverage')],
b('Qual diferença separa caso perdido e caso não avaliável?','What distinguishes a missed case from an unevaluable case?'),b('Um caso perdido tinha condições para avaliação mas não foi detectado. Um não avaliável não tinha dados necessários; essa lacuna deve ser registrada, não contada como segurança.','A missed case was evaluable but not detected. An unevaluable case lacked required data; record that gap rather than counting it as safety.'),
b('Você aumenta o limiar e zera os alertas. Isso prova que a regra melhorou?','You raise the threshold and eliminate alerts. Does that prove improvement?'),b('Não. Compare ruído reduzido com casos relevantes perdidos e cobertura. Menos alertas pode significar menos visibilidade, não menos risco.','No. Compare reduced noise with missed relevant cases and coverage. Fewer alerts may mean less visibility rather than less risk.')),
m23:unit(
b('Tráfego descreve comunicação observada, não toda intenção. Origem, destino, direção, janela e volume dão contexto. TLS protege conteúdo em trânsito e limita o que um sensor pode ler. Um fluxo grande pode ser backup autorizado ou outra atividade; correlacione com identidade, tarefa e registros antes de afirmar finalidade.','Traffic describes observed communication, not all intent. Source, destination, direction, window and volume provide context. TLS protects transit content and limits sensor visibility. A large flow may be authorized backup or another activity; correlate identity, task and records before claiming purpose.'),
b('Um sensor vê 8 MB saindo por TLS e nenhuma resposta dentro de uma janela curta. Um colega conclui “vazamento confirmado, sem retorno”.','A sensor sees 8 MB outbound over TLS and no response in a short window. A colleague concludes “confirmed leak, no return”.'),
b('O volume e a cifragem não confirmam finalidade. A janela pode ter excluído a resposta e o sensor pode observar só uma direção. Confira cobertura, tempo, destino e tarefa autorizada. Relate “transferência observada; finalidade ainda não confirmada” enquanto busca correlação.','Volume and encryption do not confirm purpose. The window may exclude the response and the sensor may observe only one direction. Check coverage, time, destination and authorized task. Report “transfer observed; purpose not yet confirmed” while correlating.'),
b('Silêncio pode significar falta de visibilidade. O laboratório não decifra TLS nem representa todos os protocolos ou fontes de rede.','Silence may mean missing visibility. The lab does not decrypt TLS or represent all network protocols and sources.'),
[b('Sensor observa uma direção','Sensor observes one direction'),b('Você amplia janela e contexto','Expand window and context'),b('Correlaciona destino e tarefa','Correlate destination and task'),b('Conclusão preserva a incerteza','Conclusion preserves uncertainty')],
b('Por que um fluxo TLS grande não prova exfiltração?','Why does a large TLS flow not prove exfiltration?'),b('TLS informa proteção do transporte, volume informa quantidade. Finalidade e autorização exigem contexto e correlação; backups legítimos também podem ter essas características.','TLS indicates transport protection and volume indicates quantity. Purpose and authorization require context and correlation; legitimate backups can have those characteristics too.'),
b('Você não viu resposta na janela de captura. Pode afirmar que ela nunca ocorreu?','You saw no response in the capture window. Can you say it never occurred?'),b('Não. Confira janela, ambas as direções e cobertura do sensor. Descreva a ausência na amostra observada, sem extrapolar para todo o sistema.','No. Check the window, both directions and sensor coverage. Describe absence in the observed sample without extrapolating to the whole system.'))
};
